// evaluate: the planes of a block's upright edge, a planar spline, two parallel lines and a line with an arc
export function c007(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(baseSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(40, 30) * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 20 * millimeter });
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 30) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skFitSpline(s1, "spline1", { "points" : [vector(0, 0) * millimeter, vector(10, 6) * millimeter, vector(20, -3) * millimeter, vector(30, 4) * millimeter] });
    skLineSegment(s1, "l1", { "start" : vector(0, 20) * millimeter, "end" : vector(30, 20) * millimeter });
    skLineSegment(s1, "l2", { "start" : vector(0, 25) * millimeter, "end" : vector(30, 25) * millimeter });
    skLineSegment(s1, "l3", { "start" : vector(40, 0) * millimeter, "end" : vector(50, 0) * millimeter });
    skArc(s1, "a1", { "start" : vector(50, 0) * millimeter, "mid" : vector(55, 5) * millimeter, "end" : vector(60, 0) * millimeter });
    skSolve(s1);
    return { "upright" : planarProbe(context, qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(40, 30, 10) * millimeter), false), "spline" : planarProbe(context, sketchEntityQuery(id + "s1", EntityType.EDGE, "spline1"), false), "parallel" : planarProbe(context, qUnion([sketchEntityQuery(id + "s1", EntityType.EDGE, "l1"), sketchEntityQuery(id + "s1", EntityType.EDGE, "l2")]), true), "lineAndArc" : planarProbe(context, qUnion([sketchEntityQuery(id + "s1", EntityType.EDGE, "l3"), sketchEntityQuery(id + "s1", EntityType.EDGE, "a1")]), true) };
}

